/* Maths MPSI · chapitre 01 : Logique et raisonnements (exercices corrigés pas à pas). */
(() => {
const R = String.raw;
const C0 = { subj: "maths", year: "mpsi", chap: 0 };

LEMME.rappels({
  "lg-ou-et": { t: "« et », « ou »", b: R`$$A\wedge B\ :\ \text{les deux};\qquad A\vee B\ :\ \text{au moins un (ou inclusif)}.$$$$x\in A\cap B\iff x\in A\wedge x\in B,\qquad x\in A\cup B\iff x\in A\vee x\in B.$$` },
  "lg-implication": { t: "L'implication", b: R`<p>« $A\Rightarrow B$ » est <b>fausse dans un seul cas</b> : $A$ vraie et $B$ fausse. Elle est vraie dès que $A$ est fausse.</p><div class="sbox">$$(A\Rightarrow B)\iff(\text{non}A\ \text{ou}\ B).$$</div>` },
  "lg-negation": { t: "Nier une phrase quantifiée", b: R`$$\begin{aligned}\neg(\forall x,\ A(x))&\iff\exists x,\ \neg A(x)\\\neg(\exists x,\ A(x))&\iff\forall x,\ \neg A(x)\\\neg(A\wedge B)&\iff\neg A\vee\neg B\\\neg(A\vee B)&\iff\neg A\wedge\neg B\\\neg(A\Rightarrow B)&\iff A\wedge\neg B\end{aligned}$$` },
  "lg-contraposee": { t: "Contraposée", b: R`<div class="sbox">$$(A\Rightarrow B)\iff(\text{non}B\Rightarrow\text{non}A).$$</div><p>Pour montrer $A\Rightarrow B$, on peut supposer $B$ fausse et montrer que $A$ est fausse.</p>` },
  "lg-disjonction": { t: "Disjonction de cas", b: R`$$C_1\vee\dots\vee C_k\text{ toujours vrai},\quad\forall i,\ C_i\Rightarrow P\qquad\Longrightarrow\qquad P.$$` },
  "lg-parite": { t: "Pair, impair", b: R`$$n\text{ pair}\iff\exists p\in\mathbb Z,\ n = 2p;\qquad n\text{ impair}\iff\exists p\in\mathbb Z,\ n = 2p+1.$$` }
});

LEMME.exercises([
/* ---------------- Logique ---------------- */
{ id: "lg-parties", ...C0, level: 1, time: "10 min",
  title: "Lire une condition sur x comme une partie de ℝ",
  enonce: R`<p>Pour chacune des assertions suivantes, déterminer l'ensemble des réels $x$ qui la rendent vraie.</p><ol style="list-style:lower-alpha"><li>$(x>0\ \text{et}\ x< 1)\ \text{ou}\ x = 0$ ;</li><li>$x>3\ \text{et}\ x< 5\ \text{et}\ x\neq4$ ;</li><li>$(x\leqslant0\ \text{et}\ x>1)\ \text{ou}\ x = 4$ ;</li><li>$x\geqslant0\Longrightarrow x\geqslant2$.</li></ol>`,
  decode: { donnees: [R`Quatre assertions qui dépendent d'un réel $x$.`], but: R`Écrire, pour chacune, l'ensemble des $x$ qui la rendent vraie, sous forme d'intervalles.`, cles: {} },
  steps: [
    { q: 1, t: "(a) Un « ou » donne une réunion", h: R`<p>Traite d'abord la parenthèse, puis ajoute le point $0$.</p>`, b: R`<p><b>La parenthèse</b> « $x>0$ et $x< 1$ » : les deux conditions doivent être vraies en même temps, c'est l'intersection $]0,+\infty[\,\cap\,]-\infty,1[\, = \,]0,1[$.</p><p><b>Le « ou »</b> : l'assertion est vraie si $x\in\,]0,1[$ <b>ou</b> si $x = 0$. On réunit les deux ensembles : $]0,1[\,\cup\{0\}$.</p><div class="sbox">$$\{x : (a)\ \text{vraie}\} = [0,1[.$$</div><p>On ferme le crochet en $0$ (car $0$ est ajouté), mais pas en $1$ ($x< 1$ strict).</p>`, rappels: ["lg-ou-et"] },
    { q: 2, t: "(b) Trois conditions en même temps", h: R`<p>« et » : intersection. Retirer $4$ coupe l'intervalle en deux.</p>`, b: R`<p>« $x>3$ et $x< 5$ » donne l'intervalle $]3,5[$. La troisième condition « $x\neq4$ » retire le point $4$ :</p><div class="sbox">$$\{x : (b)\ \text{vraie}\} = \,]3,5[\,\setminus\{4\} = \,]3,4[\,\cup\,]4,5[.$$</div>` },
    { q: 3, t: "(c) Une parenthèse impossible", h: R`<p>Peut-on avoir à la fois $x\leqslant0$ et $x>1$ ?</p>`, b: R`<p><b>La parenthèse</b> : $x\leqslant0$ et $x>1$ en même temps est impossible (un réel $\leqslant0$ est $< 1$). L'ensemble correspondant est $]-\infty,0]\cap\,]1,+\infty[\, = \emptyset$.</p><p><b>Le « ou »</b> : il ne reste que la possibilité $x = 4$. On réunit : $\emptyset\cup\{4\} = \{4\}$.</p><div class="sbox">$$\{x : (c)\ \text{vraie}\} = \{4\}.$$</div>` },
    { q: 4, t: "(d) Une implication", h: R`<p>Une implication est fausse seulement quand l'hypothèse est vraie et la conclusion fausse.</p>`, b: R`<p>On remplace l'implication par son équivalent : $(A\Rightarrow B)\iff(\text{non}A\ \text{ou}\ B)$. Ici $A$ : « $x\geqslant0$ » et $B$ : « $x\geqslant2$ ». Donc</p>$$(x\geqslant0\Rightarrow x\geqslant2)\iff(x< 0\ \text{ou}\ x\geqslant2).$$<p>Vérification par les cas :</p><ul><li>si $x< 0$ : l'hypothèse est fausse, l'implication est vraie ;</li><li>si $0\leqslant x< 2$ : l'hypothèse est vraie et la conclusion fausse, l'implication est <b>fausse</b> ;</li><li>si $x\geqslant2$ : hypothèse et conclusion vraies, l'implication est vraie.</li></ul><div class="sbox">$$\{x : (d)\ \text{vraie}\} = \,]-\infty,0[\,\cup\,[2,+\infty[.$$</div>`, rappels: ["lg-implication"] }
  ],
  piege: R`En (d), oublier les $x< 0$ : une implication dont l'hypothèse est fausse est <b>vraie</b>.`,
  methode: R`Traduire « et » par une intersection, « ou » par une réunion, et $A\Rightarrow B$ par « non $A$ ou $B$ ».`
},
{ id: "lg-tables", ...C0, level: 1, time: "15 min",
  title: "Deux équivalences par tables de vérité",
  enonce: R`<p>Soient $P$, $Q$, $R$ trois assertions. À l'aide de tables de vérité, montrer que :</p><ol style="list-style:lower-alpha"><li>$P\ \text{ou}\ (Q\ \text{et}\ R)$ équivaut à $(P\ \text{ou}\ Q)\ \text{et}\ (P\ \text{ou}\ R)$ ;</li><li>$\text{non}(P\Rightarrow Q)$ équivaut à $P\ \text{et}\ \text{non}(Q)$.</li></ol>`,
  decode: { donnees: [R`Chaque assertion vaut V (vrai) ou F (faux).`], but: R`Montrer que deux assertions composées ont toujours la même valeur.`, cles: {} },
  steps: [
    { q: 1, t: "Le principe", h: R`<p>Combien de lignes pour trois assertions ?</p>`, b: R`<p>Deux assertions sont <b>équivalentes</b> si elles ont la même valeur de vérité dans tous les cas possibles. Avec trois assertions $P,Q,R$, chacune peut valoir V ou F : il y a $2\times2\times2 = 8$ cas. On les écrit tous, ligne par ligne, et on calcule colonne par colonne avec les règles :</p><ul><li>« $A$ et $B$ » vaut V seulement si $A$ et $B$ valent V ;</li><li>« $A$ ou $B$ » vaut F seulement si $A$ et $B$ valent F ;</li><li>« $A\Rightarrow B$ » vaut F seulement si $A$ vaut V et $B$ vaut F.</li></ul>`, rappels: ["lg-ou-et", "lg-implication"] },
    { q: 2, t: "(a) La table complète", h: R`<p>Calcule d'abord $Q$ et $R$, puis $P$ ou ce résultat ; à côté, $P$ ou $Q$, $P$ ou $R$, puis leur « et ».</p>`, b: R`<p>Pour que la table reste lisible, on nomme les colonnes :</p><ul><li>$A = Q\ \text{et}\ R$, puis $G = P\ \text{ou}\ A$ (membre de gauche) ;</li><li>$B = P\ \text{ou}\ Q$, $C = P\ \text{ou}\ R$, puis $D = B\ \text{et}\ C$ (membre de droite).</li></ul>$$\begin{array}{ccc|cc|ccc}P&Q&R&A&G&B&C&D\\\hline V&V&V&V&\mathbf V&V&V&\mathbf V\\V&V&F&F&\mathbf V&V&V&\mathbf V\\V&F&V&F&\mathbf V&V&V&\mathbf V\\V&F&F&F&\mathbf V&V&V&\mathbf V\\F&V&V&V&\mathbf V&V&V&\mathbf V\\F&V&F&F&\mathbf F&V&F&\mathbf F\\F&F&V&F&\mathbf F&F&V&\mathbf F\\F&F&F&F&\mathbf F&F&F&\mathbf F\end{array}$$<p>Lecture d'une ligne, par exemple $P = F$, $Q = V$, $R = F$ : $Q$ et $R$ vaut F (car $R$ est faux), donc $P$ ou ($Q$ et $R$) vaut F ou F, soit F. De l'autre côté : $P$ ou $Q$ vaut V, $P$ ou $R$ vaut F, et V et F donne F.</p><p>Les colonnes $G$ et $D$ (en gras) sont identiques sur les $8$ lignes :</p><div class="sbox">$$P\ \text{ou}\ (Q\ \text{et}\ R)\iff(P\ \text{ou}\ Q)\ \text{et}\ (P\ \text{ou}\ R).$$</div><p>C'est la <b>distributivité</b> du « ou » sur le « et ».</p>` },
    { q: 3, t: "(b) La négation d'une implication", h: R`<p>Ici il n'y a que deux assertions : $4$ lignes.</p>`, b: R`<p>On note $I = P\Rightarrow Q$, $G = \text{non}(I)$ (gauche), $N = \text{non}(Q)$ et $D = P\ \text{et}\ N$ (droite).</p>$$\begin{array}{cc|cc|cc}P&Q&I&G&N&D\\\hline V&V&V&\mathbf F&F&\mathbf F\\V&F&F&\mathbf V&V&\mathbf V\\F&V&V&\mathbf F&F&\mathbf F\\F&F&V&\mathbf F&V&\mathbf F\end{array}$$<p>Ligne 2 : $P$ vrai et $Q$ faux, c'est le seul cas où $P\Rightarrow Q$ est faux, donc sa négation est vraie ; et $P$ et non$(Q)$ vaut V et V, soit V.</p><p>Les colonnes $G$ et $D$ coïncident :</p><div class="sbox">$$\text{non}(P\Rightarrow Q)\iff P\ \text{et}\ \text{non}(Q).$$</div><p>À retenir : <b>la négation d'une implication n'est pas une implication</b>. Pour montrer qu'une implication est fausse, on exhibe un cas où l'hypothèse est vraie et la conclusion fausse.</p>`, rappels: ["lg-negation"] }
  ],
  piege: R`Croire que la négation de « $P\Rightarrow Q$ » est « $P\Rightarrow\text{non}Q$ » ou « $\text{non}P\Rightarrow\text{non}Q$ » : c'est « $P$ et non$Q$ ».`,
  methode: R`Pour vérifier une équivalence entre assertions composées : écrire les $2^n$ cas et comparer les colonnes.`
},
{ id: "lg-billes-lourde", ...C0, level: 2, time: "10 min",
  title: "Neuf billes, une plus lourde, deux pesées",
  enonce: R`<p>On a neuf billes identiques à l'œil. Huit ont la même masse, la neuvième est plus lourde. Avec une balance à deux plateaux (qui indique seulement quel côté est le plus lourd, ou l'équilibre), comment trouver la bille lourde en <b>deux</b> pesées ?</p>`,
  decode: { donnees: [R`$9$ billes, exactement une plus lourde.`, R`Chaque pesée a $3$ issues : gauche plus lourd, droite plus lourd, équilibre.`], but: R`Une stratégie qui marche dans tous les cas en $2$ pesées.`, cles: {} },
  steps: [
    { q: 1, t: "L'idée : couper en trois", h: R`<p>Une pesée a trois issues : il faut que chacune élimine les deux tiers des candidates.</p>`, b: R`<p>Une pesée peut donner <b>trois</b> réponses : plateau gauche plus lourd, plateau droit plus lourd, équilibre. Pour en profiter, on répartit les candidates en <b>trois groupes de même taille</b> : un sur chaque plateau, un de côté.</p><ul><li>Si un plateau penche, la bille lourde est dans le groupe de ce plateau.</li><li>S'il y a équilibre, les deux plateaux ont la même masse : aucun ne contient la bille lourde, elle est dans le groupe de côté.</li></ul><p>Dans tous les cas, une pesée divise le nombre de candidates par $3$. Avec $9 = 3\times3$ billes, deux pesées suffisent : $9\to3\to1$.</p>` },
    { q: 2, t: "Première pesée", h: R`<p>Trois paquets de trois.</p>`, b: R`<p>On numérote les billes de $1$ à $9$. On pèse $\{1,2,3\}$ contre $\{4,5,6\}$.</p><ul><li>Si $\{1,2,3\}$ est plus lourd : la bille lourde est parmi $1,2,3$.</li><li>Si $\{4,5,6\}$ est plus lourd : elle est parmi $4,5,6$.</li><li>Si équilibre : elle est parmi $7,8,9$.</li></ul><p>On connaît donc un paquet de trois billes qui la contient.</p>` },
    { q: 3, t: "Deuxième pesée", h: R`<p>Même idée avec trois billes : une sur chaque plateau, une de côté.</p>`, b: R`<p>Soit $a,b,c$ les trois billes du paquet trouvé. On pèse $a$ contre $b$.</p><ul><li>Si $a$ est plus lourde : c'est $a$.</li><li>Si $b$ est plus lourde : c'est $b$.</li><li>Si équilibre : $a$ et $b$ ont la masse normale, donc c'est $c$.</li></ul><div class="sbox"><p style="margin:0">Deux pesées suffisent toujours.</p></div>` }
  ],
  piege: R`Peser $4$ contre $4$ au départ : en cas de déséquilibre, il reste $4$ candidates, et une seule pesée ne peut en départager que $3$.`,
  methode: R`Une pesée a $3$ issues : avec $k$ pesées, on peut départager au plus $3^k$ cas. Il faut donc couper en trois à chaque fois.`
},
{ id: "lg-billes-intrus", ...C0, level: 3, time: "25 min",
  title: "Neuf billes, un intrus de masse inconnue, trois pesées",
  enonce: R`<p>On a neuf billes identiques à l'œil. Toutes ont la même masse sauf une, dont on ne sait pas si elle est plus lourde ou plus légère. Avec une balance à deux plateaux, trouver cette bille en <b>trois</b> pesées.</p>`,
  decode: { donnees: [R`$9$ billes, une seule de masse différente (plus lourde ou plus légère, on l'ignore).`], but: R`Une stratégie qui identifie l'intrus en $3$ pesées dans tous les cas.`, cles: {} },
  steps: [
    { q: 1, t: "Ce qui change", h: R`<p>Un déséquilibre ne dit plus de quel côté est l'intrus.</p>`, b: R`<p>Si l'on savait que l'intrus est plus lourd, deux pesées suffiraient (exercice précédent). Ici, quand un plateau penche, l'intrus peut être <b>sur le plateau lourd</b> (s'il est lourd) <b>ou sur le plateau léger</b> (s'il est léger).</p><p>Un outil précieux : une <b>bille témoin</b>, dont on sait qu'elle a la masse normale. En pesant une bille suspecte contre un témoin, on sait si elle est l'intrus.</p><p>On numérote les billes $1,\dots,9$. <b>Première pesée</b> : $\{1,2,3\}$ contre $\{4,5,6\}$.</p>` },
    { q: 2, t: "Cas 1 : équilibre", h: R`<p>Les six billes pesées sont normales : ce sont des témoins.</p>`, b: R`<p>Les deux plateaux ont la même masse. Si l'intrus était parmi $1,\dots,6$, il rendrait son plateau plus lourd ou plus léger : impossible. Donc $1,\dots,6$ sont normales et l'intrus est parmi $7,8,9$. La bille $1$ sert de témoin.</p><ul><li><b>Deuxième pesée</b> : $1$ contre $7$. S'il y a déséquilibre, $7$ n'a pas la masse de $1$ : c'est l'intrus.</li><li>Sinon $7$ est normale. <b>Troisième pesée</b> : $1$ contre $8$. Déséquilibre : c'est $8$. Équilibre : $8$ est normale, et l'intrus est $9$.</li></ul><p>Trois pesées au plus.</p>` },
    { q: 3, t: "Cas 2 : déséquilibre, la deuxième pesée", h: R`<p>Supposons $\{1,2,3\}$ plus lourd. Mélange les plateaux : $\{1,4\}$ contre $\{2,5\}$.</p>`, b: R`<p>Les billes $7,8,9$ n'étaient pas sur la balance et la balance a penché : l'intrus est parmi $1,\dots,6$, et $9$ est un témoin. Supposons (l'autre cas est symétrique, en échangeant les noms) que $\{1,2,3\}$ soit plus lourd que $\{4,5,6\}$. Deux possibilités :</p><ul><li>l'intrus est <b>lourd</b>, et alors il est parmi $1,2,3$ ;</li><li>l'intrus est <b>léger</b>, et alors il est parmi $4,5,6$.</li></ul><p><b>Deuxième pesée</b> : $\{1,4\}$ contre $\{2,5\}$ (on laisse $3$ et $6$ de côté).</p>` },
    { q: 4, t: "Cas 2 : lire la deuxième pesée", h: R`<p>Pour chaque suspect, demande-toi de quel côté il ferait pencher la balance.</p>`, b: R`<p>On regarde ce que chaque suspect produirait :</p><ul><li>$1$ lourd, à gauche : la gauche penche. $4$ léger, à gauche : la droite penche.</li><li>$2$ lourd, à droite : la droite penche. $5$ léger, à droite : la gauche penche.</li><li>$3$ ou $6$, absents : équilibre.</li></ul><p>D'où :</p><ul><li><b>Équilibre</b> : l'intrus est $3$ (lourd) ou $6$ (léger).</li><li><b>Gauche plus lourde</b> : l'intrus est $1$ (lourd) ou $5$ (léger).</li><li><b>Droite plus lourde</b> : l'intrus est $2$ (lourd) ou $4$ (léger).</li></ul><p>Dans chaque cas, il reste deux candidates.</p>` },
    { q: 5, t: "Cas 2 : troisième pesée", h: R`<p>On compare une des deux candidates au témoin $9$.</p>`, b: R`<p>Soit $\{u,v\}$ les deux candidates restantes. <b>Troisième pesée</b> : $u$ contre le témoin $9$.</p><ul><li>Déséquilibre : $u$ n'a pas la masse normale, c'est l'intrus.</li><li>Équilibre : $u$ est normale, l'intrus est $v$.</li></ul><div class="sbox"><p style="margin:0">Dans tous les cas, l'intrus est trouvé en trois pesées (et on sait même s'il est lourd ou léger, sauf dans le cas 1 où l'intrus est $9$).</p></div>` }
  ],
  piege: R`Après un déséquilibre, chercher seulement sur le plateau lourd : l'intrus peut être une bille légère de l'autre plateau.`,
  methode: R`Garder des billes témoins et, à la deuxième pesée, faire changer de plateau certaines suspectes : la réponse de la balance les départage.`
},
/* ---------------- Quantificateurs ---------------- */
{ id: "lg-q-lire", ...C0, level: 1, time: "15 min",
  title: "Traduire des phrases quantifiées en français",
  enonce: R`<p>Soit $f : \mathbb R\to\mathbb R$. Que signifient les assertions suivantes ?</p><ol style="list-style:lower-alpha"><li>$\exists M\in\mathbb R,\ \forall x\in\mathbb R,\ f(x)\leqslant M$ ;</li><li>$\forall M\in\mathbb R,\ \exists x\in\mathbb R,\ f(x)\geqslant M$ ;</li><li>$\forall x\in\mathbb R,\ x\geqslant0\Rightarrow f(x)\geqslant0$ ;</li><li>$\forall x\in\mathbb R,\ f(x) = 0\Rightarrow x = 0$ ;</li><li>$\exists A\in\mathbb R,\ \exists C\in\mathbb R,\ \forall x\in\mathbb R,\ x\geqslant A\Rightarrow f(x) = C$.</li></ol>`,
  decode: { donnees: [R`Une fonction $f$ de $\mathbb R$ dans $\mathbb R$.`], but: R`Dire chaque phrase en français simple.`, cles: {} },
  steps: [
    { q: 1, t: "Comment lire", h: R`<p>On lit de gauche à droite : ce qui est choisi en premier ne dépend pas de ce qui vient après.</p>`, b: R`<p>On lit les quantificateurs <b>de gauche à droite</b>. Un objet introduit par $\exists$ peut dépendre de tout ce qui a été introduit <b>avant</b> lui, mais pas de ce qui vient après.</p><p>Par exemple, dans $\exists M,\ \forall x$, le nombre $M$ est choisi d'abord : <b>le même</b> $M$ doit marcher pour tous les $x$.</p>` },
    { q: 2, t: "(a) et (b)", h: R`<p>(a) : un même $M$ pour tous les $x$. (b) : pour chaque $M$, un $x$ adapté.</p>`, b: R`<p><b>(a)</b> Il existe un réel $M$ tel que toutes les valeurs $f(x)$ sont $\leqslant M$ : <b>$f$ est majorée</b> (par $M$).</p><p><b>(b)</b> Quel que soit le seuil $M$, on trouve un $x$ (qui dépend de $M$) avec $f(x)\geqslant M$ : <b>$f$ prend des valeurs aussi grandes qu'on veut</b>, autrement dit <b>$f$ n'est pas majorée</b>.</p><p>Pourquoi « pas majorée » ? Si $f$ était majorée par un $M_0$, on appliquerait (b) avec $M = M_0+1$ : on aurait $f(x)\geqslant M_0+1>M_0$, absurde. Réciproquement, si $f$ n'est pas majorée, aucun $M$ n'est un majorant, donc pour tout $M$ il existe $x$ avec $f(x)>M$, et a fortiori $f(x)\geqslant M$.</p>` },
    { q: 3, t: "(c) et (d)", h: R`<p>Une implication sous un $\forall$ ne parle que des $x$ qui vérifient l'hypothèse.</p>`, b: R`<p><b>(c)</b> Pour tout $x$ positif, $f(x)$ est positif : <b>$f$ est positive sur $\mathbb R_+$</b>. On ne dit rien de $f(x)$ pour $x< 0$.</p><p><b>(d)</b> Si $f(x) = 0$, alors $x = 0$ : <b>$f$ ne s'annule pas ailleurs qu'en $0$</b>. Attention, cela n'oblige pas $f$ à s'annuler en $0$ : par exemple $f(x) = 1$ pour tout $x$ vérifie (d), car $f(x) = 0$ n'arrive jamais (l'hypothèse est toujours fausse).</p>`, rappels: ["lg-implication"] },
    { q: 4, t: "(e)", h: R`<p>$A$ et $C$ sont choisis avant $x$.</p>`, b: R`<p>Il existe un seuil $A$ et une valeur $C$ tels que, pour tous les $x\geqslant A$, $f(x) = C$ : <b>$f$ est constante sur un intervalle $[A,+\infty[$</b>, c'est-à-dire « constante à partir d'un certain point ».</p><p>Exemple : $f(x) = \max(x,0)$ ne convient pas ; $f(x) = \min(x,1)$ convient avec $A = 1$, $C = 1$.</p>` }
  ],
  piege: R`En (d), conclure que $f(0) = 0$ : l'implication dit seulement que $0$ est le seul zéro <b>possible</b>.`,
  methode: R`Lire les quantificateurs dans l'ordre, et repérer ce qui est fixé avant le reste.`
},
{ id: "lg-q-lire-2", ...C0, level: 1, time: "10 min",
  title: "Reconnaître des propriétés d'une fonction",
  enonce: R`<p>Soit $I$ un intervalle de $\mathbb R$ et $f : I\to\mathbb R$. Exprimer en français :</p><ol style="list-style:lower-alpha"><li>$\exists C\in\mathbb R,\ \forall x\in I,\ f(x) = C$ ;</li><li>$\forall x\in I,\ f(x) = 0\Rightarrow x = 0$ ;</li><li>$\forall y\in\mathbb R,\ \exists x\in I,\ f(x) = y$ ;</li><li>$\forall x,y\in I,\ x\leqslant y\Rightarrow f(x)\leqslant f(y)$ ;</li><li>$\forall x,y\in I,\ f(x) = f(y)\Rightarrow x = y$.</li></ol>`,
  decode: { donnees: [R`Une fonction $f$ définie sur un intervalle $I$.`], but: R`Reconnaître des propriétés classiques.`, cles: {} },
  steps: [
    { q: 1, t: "(a) et (b)", h: R`<p>(a) : un même $C$ pour tous les $x$.</p>`, b: R`<p><b>(a)</b> Il existe une valeur $C$ que $f$ prend en <b>tout</b> point : <b>$f$ est constante</b>.</p><p><b>(b)</b> Le seul réel où $f$ peut s'annuler est $0$ : <b>$f$ ne peut s'annuler qu'en $0$</b> (elle n'est pas obligée de s'y annuler, et si $0\notin I$, cela veut dire que $f$ ne s'annule pas).</p>` },
    { q: 2, t: "(c) Surjectivité", h: R`<p>Chaque réel $y$ est-il atteint ?</p>`, b: R`<p>Tout réel $y$ est l'image d'au moins un $x\in I$ : <b>$f$ prend toutes les valeurs réelles</b>, c'est-à-dire <b>$f$ est surjective</b> de $I$ sur $\mathbb R$.</p>` },
    { q: 3, t: "(d) et (e)", h: R`<p>(d) : l'ordre est conservé. (e) : deux images égales viennent du même point.</p>`, b: R`<p><b>(d)</b> Si $x\leqslant y$, alors $f(x)\leqslant f(y)$ : $f$ conserve l'ordre, <b>$f$ est croissante</b>.</p><p><b>(e)</b> Si deux points ont la même image, ce sont les mêmes points : <b>$f$ ne prend jamais deux fois la même valeur</b>, c'est-à-dire <b>$f$ est injective</b>. Par contraposée, c'est la même chose que : $x\neq y\Rightarrow f(x)\neq f(y)$.</p>`, rappels: ["lg-contraposee"] }
  ],
  piege: R`Confondre (c) « tout $y$ est atteint » (surjectivité) et (e) « aucune valeur n'est atteinte deux fois » (injectivité).`,
  methode: R`Les définitions de constante, croissante, injective, surjective sont des phrases quantifiées à connaître par cœur dans les deux sens.`
},
{ id: "lg-q-ecrire", ...C0, level: 1, time: "15 min",
  title: "Écrire des propriétés avec des quantificateurs",
  enonce: R`<p>Soit $I$ un intervalle de $\mathbb R$ et $f : I\to\mathbb R$. Écrire avec des quantificateurs :</p><ol style="list-style:lower-alpha"><li>$f$ s'annule ;</li><li>$f$ est la fonction nulle ;</li><li>$f$ n'est pas constante ;</li><li>$f$ ne prend jamais deux fois la même valeur ;</li><li>$f$ admet un minimum ;</li><li>$f$ prend des valeurs arbitrairement grandes ;</li><li>$f$ s'annule au plus une fois ;</li><li>(pour $I = \mathbb R$) $f$ ne s'annule que sur $\mathbb R_+$.</li></ol>`,
  decode: { donnees: [R`Une fonction $f : I\to\mathbb R$.`], but: R`Traduire chaque phrase française en phrase quantifiée.`, cles: {} },
  steps: [
    { q: 1, t: "(a) et (b) : un point, ou tous", h: R`<p>« s'annule » : il y a au moins un zéro. « nulle » : tout point est un zéro.</p>`, b: R`<p><b>(a)</b> Il existe au moins un point où $f$ vaut $0$ :</p>$$\exists x\in I,\ f(x) = 0.$$<p><b>(b)</b> $f$ vaut $0$ en tout point :</p>$$\forall x\in I,\ f(x) = 0.$$` },
    { q: 2, t: "(c) Pas constante", h: R`<p>Nie « $\exists C,\ \forall x,\ f(x) = C$ », ou trouve deux points d'images différentes.</p>`, b: R`<p>« $f$ est constante » s'écrit $\exists C\in\mathbb R,\ \forall x\in I,\ f(x) = C$. Sa négation (on échange $\exists$ et $\forall$ et on nie la fin) :</p>$$\forall C\in\mathbb R,\ \exists x\in I,\ f(x)\neq C.$$<p>Une écriture équivalente, plus simple : il existe deux points dont les images sont différentes,</p>$$\exists x,y\in I,\ f(x)\neq f(y).$$<p>(Si $f(x)\neq f(y)$, aucune constante $C$ ne peut valoir à la fois $f(x)$ et $f(y)$ ; réciproquement, si $f$ n'est pas constante, avec $C = f(x_0)$ on trouve $y$ tel que $f(y)\neq f(x_0)$.)</p>`, rappels: ["lg-negation"] },
    { q: 3, t: "(d) Injectivité", h: R`<p>Deux points différents ont des images différentes.</p>`, b: R`$$\forall x,y\in I,\ x\neq y\Rightarrow f(x)\neq f(y),$$<p>ou, de façon équivalente (contraposée de l'implication) :</p>$$\forall x,y\in I,\ f(x) = f(y)\Rightarrow x = y.$$`, rappels: ["lg-contraposee"] },
    { q: 4, t: "(e) et (f)", h: R`<p>Un minimum est une valeur atteinte en un point $a$ et inférieure à toutes les autres.</p>`, b: R`<p><b>(e)</b> $f$ admet un minimum s'il existe un point $a$ où la valeur $f(a)$ est inférieure ou égale à toutes les valeurs de $f$ :</p>$$\exists a\in I,\ \forall x\in I,\ f(x)\geqslant f(a).$$<p>L'ordre compte : $a$ est choisi <b>avant</b> $x$, c'est le même point pour tous les $x$.</p><p><b>(f)</b> Quel que soit le seuil $M$, $f$ le dépasse quelque part :</p>$$\forall M\in\mathbb R,\ \exists x\in I,\ f(x)>M.$$<p>C'est exactement « $f$ n'est pas majorée ».</p>` },
    { q: 5, t: "(g) et (h)", h: R`<p>« au plus une fois » : deux zéros sont forcément égaux.</p>`, b: R`<p><b>(g)</b> S'il y a deux zéros, ils sont égaux :</p>$$\forall x,y\in I,\ \big(f(x) = 0\ \text{et}\ f(y) = 0\big)\Rightarrow x = y.$$<p>Cette phrase est vraie aussi si $f$ ne s'annule pas du tout (l'hypothèse n'est jamais vérifiée) : c'est bien « <b>au plus</b> une fois ».</p><p><b>(h)</b> Tout zéro de $f$ est positif :</p>$$\forall x\in\mathbb R,\ f(x) = 0\Rightarrow x\geqslant0.$$` }
  ],
  piege: R`En (e), écrire $\forall x,\ \exists a,\ f(x)\geqslant f(a)$ : c'est toujours vrai (prendre $a = x$). L'ordre des quantificateurs change le sens.`,
  methode: R`Repérer les mots « il existe / au moins un » ($\exists$) et « tous / quel que soit » ($\forall$), puis vérifier l'ordre : ce qui ne doit pas dépendre de $x$ vient avant $\forall x$.`
},
{ id: "lg-q-nier", ...C0, level: 2, time: "15 min",
  title: "Nier des phrases quantifiées",
  enonce: R`<p>Soit $f : \mathbb R\to\mathbb R$. Écrire la négation de chacune des assertions suivantes :</p><ol style="list-style:lower-alpha"><li>$\exists M\in\mathbb R,\ \big(\forall x\in\mathbb R,\ f(x)\geqslant M\big)\ \text{ou}\ \big(\forall x\in\mathbb R,\ f(x)\leqslant M\big)$ ;</li><li>$\forall x\in\mathbb R,\ f(x)\geqslant0\Rightarrow x\geqslant0$ ;</li><li>$\forall(x,y)\in\mathbb R^2,\ x\leqslant y\Rightarrow f(x)\leqslant f(y)$ ;</li><li>$\forall a\in\mathbb R,\ \forall\varepsilon>0,\ \exists\alpha>0,\ \forall x\in\mathbb R,\ |x-a|\leqslant\alpha\Rightarrow|f(x)-f(a)|\leqslant\varepsilon$.</li></ol>`,
  decode: { donnees: [R`Quatre phrases quantifiées sur une fonction $f$.`], but: R`Écrire leurs négations, sans « non » devant.`, cles: {} },
  steps: [
    { q: 1, t: "La méthode", h: R`<p>Chaque $\forall$ devient $\exists$, chaque $\exists$ devient $\forall$, dans le même ordre ; puis on nie la phrase finale.</p>`, b: R`<p>Règles :</p><ul><li>$\text{non}(\forall x,\ A)\iff\exists x,\ \text{non}A$ et $\text{non}(\exists x,\ A)\iff\forall x,\ \text{non}A$ ;</li><li>$\text{non}(A\ \text{ou}\ B)\iff\text{non}A\ \text{et}\ \text{non}B$ ;</li><li>$\text{non}(A\Rightarrow B)\iff A\ \text{et}\ \text{non}B$ ;</li><li>la négation de $\leqslant$ est $>$, celle de $\geqslant$ est $< $.</li></ul><p>Les ensembles où vivent les variables ($x\in\mathbb R$, $\varepsilon>0$…) <b>ne changent pas</b>.</p>`, rappels: ["lg-negation"] },
    { q: 2, t: "(a)", h: R`<p>$\exists M$ devient $\forall M$ ; le « ou » devient « et ».</p>`, b: R`<p>On nie $\exists M$ : il devient $\forall M$. On nie le « ou » : il devient un « et » de deux négations. Chaque $\forall x,\ f(x)\geqslant M$ devient $\exists x,\ f(x)< M$ :</p><div class="sbox">$$\forall M\in\mathbb R,\ \big(\exists x\in\mathbb R,\ f(x)< M\big)\ \text{et}\ \big(\exists x\in\mathbb R,\ f(x)>M\big).$$</div><p>Sens : l'assertion de départ dit que $f$ est minorée ou majorée par un même nombre $M$. Sa négation : quel que soit $M$, $f$ prend des valeurs plus petites et des valeurs plus grandes que $M$.</p>` },
    { q: 3, t: "(b) et (c) : une implication sous un ∀", h: R`<p>$\text{non}(A\Rightarrow B)$ s'écrit $A$ et non$B$.</p>`, b: R`<p><b>(b)</b> $\forall x$ devient $\exists x$, et $\text{non}(f(x)\geqslant0\Rightarrow x\geqslant0)$ devient $f(x)\geqslant0$ et $x< 0$ :</p><div class="sbox">$$\exists x\in\mathbb R,\ f(x)\geqslant0\ \text{et}\ x< 0.$$</div><p><b>(c)</b> De même :</p><div class="sbox">$$\exists(x,y)\in\mathbb R^2,\ x\leqslant y\ \text{et}\ f(x)>f(y).$$</div><p>C'est « $f$ n'est pas croissante » : on trouve deux points dans le bon ordre dont les images sont dans le mauvais ordre.</p>`, rappels: ["lg-implication"] },
    { q: 4, t: "(d) Quatre quantificateurs", h: R`<p>On procède quantificateur par quantificateur, de gauche à droite.</p>`, b: R`<p>On remplace successivement :</p><ul><li>$\forall a\in\mathbb R$ devient $\exists a\in\mathbb R$ ;</li><li>$\forall\varepsilon>0$ devient $\exists\varepsilon>0$ (la condition $\varepsilon>0$ reste) ;</li><li>$\exists\alpha>0$ devient $\forall\alpha>0$ ;</li><li>$\forall x\in\mathbb R$ devient $\exists x\in\mathbb R$ ;</li><li>l'implication $|x-a|\leqslant\alpha\Rightarrow|f(x)-f(a)|\leqslant\varepsilon$ devient $|x-a|\leqslant\alpha$ et $|f(x)-f(a)|>\varepsilon$.</li></ul><div class="sbox">$$\exists a\in\mathbb R,\ \exists\varepsilon>0,\ \forall\alpha>0,\ \exists x\in\mathbb R,\ |x-a|\leqslant\alpha\ \text{et}\ |f(x)-f(a)|>\varepsilon.$$</div><p>L'assertion de départ dit que $f$ est continue en tout point $a$. Sa négation : il existe un point $a$ où $f$ n'est pas continue.</p>` }
  ],
  piege: R`Nier $\varepsilon>0$ en $\varepsilon\leqslant0$ : la condition sur $\varepsilon$ décrit seulement où vit la variable, elle ne se nie pas.`,
  methode: R`Échanger $\forall$ et $\exists$ sans changer l'ordre, garder les domaines, nier la phrase finale ($A\Rightarrow B$ devient $A$ et non $B$).`
},
{ id: "lg-q-nier-2", ...C0, level: 1, time: "10 min",
  title: "Négations de propriétés usuelles",
  enonce: R`<p>Soit $I$ un intervalle non vide de $\mathbb R$ et $f : I\to\mathbb R$. Écrire la négation de :</p><ol style="list-style:lower-alpha"><li>$\forall x\in I,\ f(x)\neq0$ ;</li><li>$\forall y\in\mathbb R,\ \exists x\in I,\ f(x) = y$ ;</li><li>$\exists M\in\mathbb R,\ \forall x\in I,\ |f(x)|\leqslant M$ ;</li><li>$\forall x,y\in I,\ x\leqslant y\Rightarrow f(x)\leqslant f(y)$ ;</li><li>$\forall x,y\in I,\ f(x) = f(y)\Rightarrow x = y$ ;</li><li>$\forall x\in I,\ f(x)>0\Rightarrow x\leqslant0$.</li></ol>`,
  decode: { donnees: [R`Six phrases quantifiées.`], but: R`Écrire leurs négations.`, cles: {} },
  steps: [
    { q: 1, t: "(a), (b), (c)", h: R`<p>Échange $\forall$ et $\exists$, nie la fin.</p>`, b: R`<p><b>(a)</b> « $f$ ne s'annule pas » devient « $f$ s'annule » :</p>$$\exists x\in I,\ f(x) = 0.$$<p><b>(b)</b> « $f$ est surjective » devient : il existe un réel $y$ que $f$ n'atteint jamais,</p>$$\exists y\in\mathbb R,\ \forall x\in I,\ f(x)\neq y.$$<p><b>(c)</b> « $f$ est bornée » devient : quel que soit $M$, $|f|$ le dépasse quelque part,</p>$$\forall M\in\mathbb R,\ \exists x\in I,\ |f(x)|>M.$$`, rappels: ["lg-negation"] },
    { q: 2, t: "(d), (e), (f) : implications", h: R`<p>$\text{non}(A\Rightarrow B)\iff A$ et non$B$.</p>`, b: R`<p><b>(d)</b> « $f$ est croissante » devient « $f$ n'est pas croissante » :</p>$$\exists x,y\in I,\ x\leqslant y\ \text{et}\ f(x)>f(y).$$<p><b>(e)</b> « $f$ est injective » devient : deux points différents ont la même image,</p>$$\exists x,y\in I,\ f(x) = f(y)\ \text{et}\ x\neq y.$$<p><b>(f)</b> La négation de « $x\leqslant0$ » est « $x>0$ » :</p>$$\exists x\in I,\ f(x)>0\ \text{et}\ x>0.$$` }
  ],
  piege: R`Nier « croissante » en « décroissante » : une fonction peut n'être ni l'une ni l'autre.`,
  methode: R`Une négation se vérifie en se demandant : « exactement une des deux phrases est-elle vraie, pour toute fonction ? »`
},
{ id: "lg-q-ordre", ...C0, level: 2, time: "15 min",
  title: "L'ordre des quantificateurs change le sens",
  enonce: R`<p>Soit $f : E\to F$ une application.</p><ol style="list-style:lower-alpha"><li>Comparer le sens de « $\forall x\in E,\ \exists y\in F,\ y = f(x)$ » et de « $\exists y\in F,\ \forall x\in E,\ y = f(x)$ ».</li><li>Comparer le sens de « $\forall y\in F,\ \exists x\in E,\ y = f(x)$ » et de « $\exists x\in E,\ \forall y\in F,\ y = f(x)$ ».</li><li>Soit $\mathcal P(x,y)$ une assertion qui dépend de $(x,y)\in E\times F$. Laquelle des deux assertions « $\exists x\in E,\ \forall y\in F,\ \mathcal P(x,y)$ » et « $\forall y\in F,\ \exists x\in E,\ \mathcal P(x,y)$ » entraîne l'autre ? Pourquoi ne sont-elles pas équivalentes en général ?</li></ol>`,
  decode: { donnees: [R`Une application $f : E\to F$ ($E$, $F$ non vides).`], but: R`Voir l'effet de l'échange d'un $\forall$ et d'un $\exists$.`, cles: {} },
  steps: [
    { q: 1, t: "(a)", h: R`<p>Dans la première, $y$ peut dépendre de $x$ ; dans la seconde, non.</p>`, b: R`<p><b>« $\forall x,\ \exists y,\ y = f(x)$ »</b> : pour chaque $x$, on cherche un $y$ égal à $f(x)$. Il suffit de prendre $y = f(x)$ : cette assertion est <b>toujours vraie</b> (elle dit juste que $f(x)$ existe).</p><p><b>« $\exists y,\ \forall x,\ y = f(x)$ »</b> : un <b>même</b> $y$ est égal à $f(x)$ pour tous les $x$. Toutes les images valent $y$ : <b>$f$ est constante</b>.</p>` },
    { q: 2, t: "(b)", h: R`<p>La première est la surjectivité.</p>`, b: R`<p><b>« $\forall y,\ \exists x,\ y = f(x)$ »</b> : tout élément de $F$ a un antécédent, <b>$f$ est surjective</b>.</p><p><b>« $\exists x,\ \forall y,\ y = f(x)$ »</b> : il y a un $x$ tel que <b>tous</b> les éléments $y$ de $F$ sont égaux à $f(x)$. Donc $F$ a un seul élément : <b>$F$ est un singleton</b> (et alors $f$ est forcément constante et surjective).</p>` },
    { q: 3, t: "(c) Le sens qui marche", h: R`<p>Si un même $x_0$ convient pour tous les $y$, il convient pour chaque $y$.</p>`, b: R`<p>Supposons $\exists x\in E,\ \forall y\in F,\ \mathcal P(x,y)$ : on fixe un tel $x_0$, il vérifie $\mathcal P(x_0,y)$ pour tout $y$.</p><p>Soit maintenant $y\in F$ quelconque. On cherche un $x$ avec $\mathcal P(x,y)$ : $x = x_0$ convient. Donc $\forall y,\ \exists x,\ \mathcal P(x,y)$.</p><div class="sbox">$$\big(\exists x,\ \forall y,\ \mathcal P(x,y)\big)\Longrightarrow\big(\forall y,\ \exists x,\ \mathcal P(x,y)\big).$$</div>` },
    { q: 4, t: "(c) La réciproque est fausse", h: R`<p>Cherche $\mathcal P$ où le bon $x$ dépend de $y$.</p>`, b: R`<p>Dans « $\forall y,\ \exists x$ », le $x$ peut <b>dépendre de $y$</b> ; dans « $\exists x,\ \forall y$ », un seul $x$ doit servir pour tous les $y$. C'est plus exigeant.</p><p><b>Contre-exemple</b> : $E = F = \mathbb R$ et $\mathcal P(x,y)$ : « $x>y$ ».</p><ul><li>$\forall y,\ \exists x,\ x>y$ est vraie : pour chaque $y$, $x = y+1$ convient.</li><li>$\exists x,\ \forall y,\ x>y$ est fausse : ce $x$ devrait être plus grand que $y = x$, c'est-à-dire $x>x$, impossible.</li></ul><p>Les deux assertions ne sont donc pas équivalentes.</p>` }
  ],
  piege: R`Échanger $\forall$ et $\exists$ « parce que ça se lit pareil » : « pour tout $y$ il existe $x$ » autorise un $x$ différent pour chaque $y$.`,
  methode: R`$\exists\forall\Rightarrow\forall\exists$ est toujours vrai ; la réciproque est fausse en général.`
},
{ id: "lg-q-pqr", ...C0, level: 2, time: "15 min",
  title: "Trois propriétés d'une fonction continue",
  enonce: R`<p>Soit $f : \mathbb R\to\mathbb R$ continue. On note</p>$$P : \forall x\in\mathbb R,\ f(x) = 0,\qquad Q : \exists x\in\mathbb R,\ f(x) = 0,$$$$R : \big(\forall x\in\mathbb R,\ f(x)>0\big)\ \text{ou}\ \big(\forall x\in\mathbb R,\ f(x)< 0\big).$$<p>Parmi les implications suivantes, lesquelles sont vraies pour toute fonction continue ?</p><ol style="list-style:lower-alpha"><li>$P\Rightarrow Q$ ;</li><li>$Q\Rightarrow P$ ;</li><li>$Q\Rightarrow R$ ;</li><li>$\text{non}(R)\Rightarrow Q$ ;</li><li>$\text{non}(Q)\Rightarrow\text{non}(P)$ ;</li><li>$\text{non}(P)\Rightarrow\text{non}(R)$.</li></ol>`,
  decode: { donnees: [R`$f$ continue sur $\mathbb R$.`, R`$P$ : $f$ est nulle. $Q$ : $f$ s'annule. $R$ : $f$ est de signe strict constant.`], but: R`Démontrer les implications vraies et donner un contre-exemple pour les fausses.`, cles: {} },
  steps: [
    { q: 1, t: "(a) P ⇒ Q", h: R`<p>Si $f$ est nulle partout, elle est nulle en $0$.</p>`, b: R`<p>Supposons $P$ : $f(x) = 0$ pour tout $x$. En particulier $f(0) = 0$ : le réel $x = 0$ convient dans $Q$. <b>(a) est vraie.</b></p>` },
    { q: 2, t: "(b) et (c) : contre-exemples", h: R`<p>Teste $f(x) = x$.</p>`, b: R`<p>Pour montrer qu'une implication $A\Rightarrow B$ est fausse, on donne une fonction pour laquelle $A$ est vraie et $B$ fausse.</p><p>Prenons $f(x) = x$, continue. Elle s'annule en $0$ : $Q$ est vraie.</p><ul><li>$P$ est fausse ($f(1) = 1\neq0$) : <b>(b) $Q\Rightarrow P$ est fausse</b>.</li><li>$R$ est fausse : $f(1) = 1>0$ donc « $\forall x,\ f(x)< 0$ » est faux, et $f(-1) = -1< 0$ donc « $\forall x,\ f(x)>0$ » est faux. <b>(c) $Q\Rightarrow R$ est fausse</b>.</li></ul>`, rappels: ["lg-implication"] },
    { q: 3, t: "(d) non(R) ⇒ Q : le TVI", h: R`<p>Écris non$(R)$ : il y a un point où $f\leqslant0$ et un point où $f\geqslant0$.</p>`, b: R`<p>On écrit la négation de $R$ (un « ou » devient un « et ») :</p>$$\text{non}(R) : \big(\exists a\in\mathbb R,\ f(a)\leqslant0\big)\ \text{et}\ \big(\exists b\in\mathbb R,\ f(b)\geqslant0\big).$$<p>Supposons non$(R)$ et prenons ces points $a$ et $b$. Si $a = b$, alors $f(a)\leqslant0\leqslant f(a)$, donc $f(a) = 0$. Sinon, $f$ est continue sur le segment d'extrémités $a$ et $b$, et $0$ est compris entre $f(a)$ et $f(b)$.</p><p><b>Théorème des valeurs intermédiaires</b> : il existe $c$ entre $a$ et $b$ avec $f(c) = 0$. Donc $Q$ est vraie. <b>(d) est vraie</b> (et c'est ici que la continuité sert).</p>`, rappels: ["lg-negation"] },
    { q: 4, t: "(e) et (f)", h: R`<p>(e) est la contraposée de (a).</p>`, b: R`<p><b>(e)</b> $\text{non}(Q)\Rightarrow\text{non}(P)$ est la <b>contraposée</b> de $P\Rightarrow Q$, qui est vraie par (a). Une implication et sa contraposée ont la même valeur : <b>(e) est vraie</b>.</p><p><b>(f)</b> Contre-exemple : $f(x) = 1$ pour tout $x$. $P$ est fausse ($f(0) = 1\neq0$), donc non$(P)$ est vraie. Mais $R$ est vraie ($f(x)>0$ pour tout $x$), donc non$(R)$ est fausse. <b>(f) est fausse</b>.</p><div class="sbox">$$\text{Implications vraies : (a), (d), (e).}$$</div>`, rappels: ["lg-contraposee"] }
  ],
  piege: R`Oublier la continuité en (d) : sans elle, $f = -1$ sur $]-\infty,0[$ et $f = 1$ sur $[0,+\infty[$ vérifie non$(R)$ sans s'annuler.`,
  methode: R`Une implication vraie se démontre ; une implication fausse se réfute par <b>un seul</b> contre-exemple.`
},
{ id: "lg-epsilon", ...C0, level: 2, time: "15 min",
  title: "Un réel plus petit que tout ε est nul",
  enonce: R`<p>Soit $a\in\mathbb R$.</p><ol style="list-style:lower-alpha"><li>Montrer que $\big(\forall\varepsilon\geqslant0,\ |a|\leqslant\varepsilon\big)\Rightarrow a = 0$.</li><li>Montrer que $\big(\forall\varepsilon>0,\ |a|\leqslant\varepsilon\big)\Rightarrow a = 0$.</li><li>Soient $x,y$ réels. Montrer que $x^2+y^2 = 0\iff(x = 0\ \text{et}\ y = 0)$.</li></ol>`,
  decode: { donnees: [R`$|a|\geqslant0$, avec égalité si et seulement si $a = 0$.`], but: R`Montrer qu'un réel est nul à partir d'inégalités.`, cles: {} },
  steps: [
    { q: 1, t: "(a) On choisit ε = 0", h: R`<p>Une propriété vraie pour tout $\varepsilon\geqslant0$ l'est pour $\varepsilon = 0$.</p>`, b: R`<p>Supposons $|a|\leqslant\varepsilon$ pour tout $\varepsilon\geqslant0$. On l'applique au cas particulier $\varepsilon = 0$ (qui vérifie bien $\varepsilon\geqslant0$) : $|a|\leqslant0$.</p><p>Or une valeur absolue est toujours positive : $|a|\geqslant0$. Donc $|a| = 0$, c'est-à-dire $a = 0$.</p>` },
    { q: 2, t: "(b) Par contraposée", h: R`<p>Ici $\varepsilon = 0$ est interdit. Suppose $a\neq0$ et trouve un $\varepsilon>0$ trop petit.</p>`, b: R`<p>On ne peut plus prendre $\varepsilon = 0$. On raisonne <b>par contraposée</b> : on montre que si $a\neq0$, alors l'hypothèse est fausse, c'est-à-dire (négation) :</p>$$\exists\varepsilon>0,\ |a|>\varepsilon.$$<p>Supposons $a\neq0$. Alors $|a|>0$. On choisit $\varepsilon = \frac{|a|}2$ :</p><ul><li>$\varepsilon>0$, car $|a|>0$ ;</li><li>$|a| = 2\varepsilon>\varepsilon$, car $\varepsilon>0$.</li></ul><p>On a trouvé un $\varepsilon>0$ avec $|a|>\varepsilon$ : l'hypothèse « $\forall\varepsilon>0,\ |a|\leqslant\varepsilon$ » est fausse. Par contraposée :</p><div class="sbox">$$\big(\forall\varepsilon>0,\ |a|\leqslant\varepsilon\big)\Rightarrow a = 0.$$</div>`, rappels: ["lg-contraposee", "lg-negation"] },
    { q: 3, t: "(c) Une somme de carrés nulle", h: R`<p>Sens ⇒ : $x^2\leqslant x^2+y^2$.</p>`, b: R`<p><b>Sens ⇐</b> : si $x = y = 0$, alors $x^2+y^2 = 0+0 = 0$.</p><p><b>Sens ⇒</b> : supposons $x^2+y^2 = 0$. Comme $y^2\geqslant0$ (un carré est positif) :</p>$$0\leqslant x^2\leqslant x^2+y^2 = 0,$$<p>donc $x^2 = 0$, puis $x = 0$ (un produit $x\cdot x$ est nul seulement si $x = 0$). De même, $0\leqslant y^2\leqslant x^2+y^2 = 0$ donne $y = 0$.</p><div class="sbox">$$x^2+y^2 = 0\iff x = y = 0.$$</div>` }
  ],
  piege: R`En (b), prendre $\varepsilon = 0$ : ce n'est pas autorisé, l'hypothèse ne parle que des $\varepsilon>0$.`,
  methode: R`Pour montrer qu'un réel positif est nul, montrer qu'il est plus petit que tout $\varepsilon>0$ ; par contraposée, choisir $\varepsilon$ égal à la moitié de ce réel.`
},
/* ---------------- Raisonnements ---------------- */
{ id: "lg-sqrt2", ...C0, level: 1, time: "15 min", classique: true,
  title: "√2 est irrationnel",
  enonce: R`<p>Montrer que $\sqrt2$ n'est pas un nombre rationnel.</p>`,
  decode: { donnees: [R`Un rationnel s'écrit $\frac pq$ avec $p\in\mathbb Z$, $q\in\mathbb N^\ast$, et on peut choisir la fraction irréductible.`], but: R`Montrer qu'aucune fraction n'est égale à $\sqrt2$.`, cles: {} },
  steps: [
    { q: 1, t: "Raisonner par l'absurde", h: R`<p>Suppose $\sqrt2 = \frac pq$ avec une fraction irréductible.</p>`, b: R`<p>On suppose le contraire de ce qu'on veut montrer : $\sqrt2\in\mathbb Q$. On peut alors écrire</p>$$\sqrt2 = \frac pq,\qquad p\in\mathbb N^\ast,\ q\in\mathbb N^\ast,$$<p>avec une fraction <b>irréductible</b> : $p$ et $q$ n'ont aucun diviseur commun autre que $1$ (on simplifie la fraction autant que possible). On va aboutir à une contradiction.</p>`, rappels: ["absurde"] },
    { q: 2, t: "Élever au carré", h: R`<p>$2 = \frac{p^2}{q^2}$.</p>`, b: R`<p>On élève au carré : $2 = \frac{p^2}{q^2}$, puis on multiplie par $q^2$ :</p>$$p^2 = 2q^2.$$<p>Donc $p^2$ est pair.</p>` },
    { q: 3, t: "p est pair", h: R`<p>Le carré d'un impair est impair.</p>`, b: R`<p>Montrons que $p$ est pair, par contraposée : si $p$ est impair, $p = 2k+1$ avec $k\in\mathbb N$, et</p>$$p^2 = (2k+1)^2 = 4k^2+4k+1 = 2(2k^2+2k)+1,$$<p>qui est impair. Donc « $p$ impair $\Rightarrow p^2$ impair », et par contraposée « $p^2$ pair $\Rightarrow p$ pair ». Comme $p^2$ est pair, $p$ est pair : $p = 2m$ avec $m\in\mathbb N^\ast$.</p>`, rappels: ["lg-contraposee", "lg-parite"] },
    { q: 4, t: "q est pair aussi : contradiction", h: R`<p>Remplace $p$ par $2m$ dans $p^2 = 2q^2$.</p>`, b: R`<p>On remplace : $(2m)^2 = 2q^2$, soit $4m^2 = 2q^2$, et en divisant par $2$ :</p>$$q^2 = 2m^2.$$<p>Donc $q^2$ est pair, et par le même argument qu'à l'étape précédente, $q$ est pair.</p><p>Ainsi $p$ et $q$ sont tous deux divisibles par $2$ : la fraction $\frac pq$ n'est pas irréductible. C'est une contradiction. L'hypothèse $\sqrt2\in\mathbb Q$ est donc fausse :</p><div class="sbox">$$\sqrt2\notin\mathbb Q.$$</div>` }
  ],
  piege: R`Oublier de supposer la fraction irréductible : sans cela, « $p$ et $q$ pairs » n'est pas une contradiction.`,
  methode: R`Pour montrer qu'un nombre n'est pas rationnel : par l'absurde, écrire une fraction irréductible et trouver un diviseur commun.`
},
{ id: "lg-sqrt2-somme", ...C0, level: 1, time: "10 min",
  title: "Rationnel plus √2, et rationnels comme sommes d'irrationnels",
  enonce: R`<p>On admet que $\sqrt2\notin\mathbb Q$.</p><ol style="list-style:lower-alpha"><li>Montrer que pour tout $x\in\mathbb Q$, $x+\sqrt2\notin\mathbb Q$.</li><li>Montrer que tout nombre rationnel est la somme de deux nombres irrationnels.</li></ol>`,
  decode: { donnees: [R`$\sqrt2$ est irrationnel.`, R`La somme et la différence de deux rationnels sont rationnelles.`], but: R`Deux propriétés des irrationnels.`, cles: {} },
  steps: [
    { q: 1, t: "(a) Par l'absurde", h: R`<p>Si $x+\sqrt2 = y$ est rationnel, isole $\sqrt2$.</p>`, b: R`<p>Soit $x\in\mathbb Q$. Supposons par l'absurde que $y = x+\sqrt2$ soit rationnel. Alors</p>$$\sqrt2 = y-x.$$<p>Or $y$ et $x$ sont rationnels, et la différence de deux rationnels est rationnelle : si $y = \frac ab$ et $x = \frac cd$, alors $y-x = \frac{ad-bc}{bd}$. Donc $\sqrt2\in\mathbb Q$, ce qui contredit l'hypothèse.</p><div class="sbox">$$\forall x\in\mathbb Q,\quad x+\sqrt2\notin\mathbb Q.$$</div>`, rappels: ["absurde"] },
    { q: 2, t: "(b) Une écriture explicite", h: R`<p>Écris $r = (r-\sqrt2)+\sqrt2$.</p>`, b: R`<p>Soit $r\in\mathbb Q$. On écrit</p>$$r = (r-\sqrt2)+\sqrt2.$$<ul><li>$\sqrt2$ est irrationnel.</li><li>$r-\sqrt2$ est irrationnel. En effet, supposons par l'absurde $r-\sqrt2 = q\in\mathbb Q$. Alors $\sqrt2 = r-q$ est la différence de deux rationnels, donc rationnel : contradiction.</li></ul><p>Ainsi $r$ est la somme des deux irrationnels $r-\sqrt2$ et $\sqrt2$.</p><p>Exemple : $1 = (1-\sqrt2)+\sqrt2$, et $0 = (-\sqrt2)+\sqrt2$.</p>` }
  ],
  piege: R`Croire que la somme de deux irrationnels est toujours irrationnelle : $(-\sqrt2)+\sqrt2 = 0$.`,
  methode: R`Pour montrer qu'un nombre n'est pas rationnel, supposer qu'il l'est et en déduire que $\sqrt2$ est rationnel.`
},
{ id: "lg-parite-cube", ...C0, level: 1, time: "10 min",
  title: "n(n²+1)/2 est un entier naturel",
  enonce: R`<p>Montrer que pour tout $n\in\mathbb N$, le nombre $\dfrac{n(n^2+1)}2$ est un entier naturel.</p>`,
  decode: { donnees: [R`$n\in\mathbb N$ est pair ou impair.`], but: R`Montrer que $n(n^2+1)$ est pair.`, cles: {} },
  steps: [
    { q: 1, t: "L'idée : disjonction de cas", h: R`<p>Il suffit que $n$ ou $n^2+1$ soit pair.</p>`, b: R`<p>Le nombre $n(n^2+1)$ est un entier naturel. Pour que sa moitié soit un entier, il faut et il suffit qu'il soit pair. On sépare les deux cas possibles : $n$ pair, $n$ impair.</p>`, rappels: ["lg-disjonction", "lg-parite"] },
    { q: 2, t: "Cas n pair", h: R`<p>$n = 2p$.</p>`, b: R`<p>On écrit $n = 2p$ avec $p\in\mathbb N$. Alors</p>$$\frac{n(n^2+1)}2 = \frac{2p\,(n^2+1)}2 = p\,(n^2+1),$$<p>produit de deux entiers naturels : c'est un entier naturel.</p>` },
    { q: 3, t: "Cas n impair", h: R`<p>$n = 2p+1$ : développe $n^2+1$.</p>`, b: R`<p>On écrit $n = 2p+1$ avec $p\in\mathbb N$. On développe avec $(a+b)^2 = a^2+2ab+b^2$ :</p>$$n^2+1 = (2p+1)^2+1 = 4p^2+4p+1+1 = 4p^2+4p+2 = 2(2p^2+2p+1).$$<p>Donc</p>$$\frac{n(n^2+1)}2 = \frac{n\cdot2(2p^2+2p+1)}2 = n\,(2p^2+2p+1),$$<p>produit de deux entiers naturels : c'est un entier naturel.</p><div class="sbox">$$\forall n\in\mathbb N,\quad\frac{n(n^2+1)}2\in\mathbb N.$$</div>` }
  ],
  piege: R`Ne traiter qu'un exemple ($n = 3$ donne $15$) : un exemple ne prouve pas un « pour tout ».`,
  methode: R`Pour une question de parité, distinguer $n = 2p$ et $n = 2p+1$, puis factoriser par $2$.`
},
{ id: "lg-pair-impair", ...C0, level: 1, time: "8 min",
  title: "Aucun entier n'est à la fois pair et impair",
  enonce: R`<p>On note $\mathcal P = \{2k : k\in\mathbb Z\}$ l'ensemble des entiers pairs et $\mathcal I = \{2k+1 : k\in\mathbb Z\}$ celui des entiers impairs. Démontrer que $\mathcal P\cap\mathcal I = \emptyset$.</p>`,
  decode: { donnees: [R`Les définitions de $\mathcal P$ et $\mathcal I$.`], but: R`Montrer qu'aucun entier n'appartient aux deux ensembles.`, cles: {} },
  steps: [
    { q: 1, t: "Par l'absurde", h: R`<p>Prends $x$ dans l'intersection et écris les deux définitions, avec <b>deux</b> entiers différents.</p>`, b: R`<p>Supposons par l'absurde $\mathcal P\cap\mathcal I\neq\emptyset$, et soit $x\in\mathcal P\cap\mathcal I$.</p><ul><li>$x\in\mathcal P$ : il existe $k\in\mathbb Z$ tel que $x = 2k$.</li><li>$x\in\mathcal I$ : il existe $\ell\in\mathbb Z$ tel que $x = 2\ell+1$.</li></ul><p>Les entiers $k$ et $\ell$ n'ont aucune raison d'être égaux : on leur donne deux noms différents.</p>`, rappels: ["absurde"] },
    { q: 2, t: "La contradiction", h: R`<p>Égalise les deux écritures et isole $k-\ell$.</p>`, b: R`<p>On égalise : $2k = 2\ell+1$, donc $2k-2\ell = 1$, soit $2(k-\ell) = 1$ et</p>$$k-\ell = \frac12.$$<p>Mais $k-\ell$ est la différence de deux entiers, donc un entier, alors que $\frac12$ n'est pas un entier ($0< \frac12< 1$). Contradiction.</p><div class="sbox">$$\mathcal P\cap\mathcal I = \emptyset.$$</div>` }
  ],
  piege: R`Écrire $x = 2k$ et $x = 2k+1$ avec le <b>même</b> $k$ : on obtient $0 = 1$, mais on n'a rien démontré, car rien n'impose que ce soit le même entier.`,
  methode: R`Quand on utilise deux « il existe », on donne deux noms différents aux objets obtenus.`
},
{ id: "lg-verifier", ...C0, level: 1, time: "10 min",
  title: "Trois vérifications directes",
  enonce: R`<ol style="list-style:lower-alpha"><li>Montrer que $x^2+x+1>0$ pour tout réel $x$.</li><li>Montrer que si le produit de deux réels est nul, l'un des deux est nul.</li><li>Montrer que pour tout entier naturel $n$, il existe un nombre premier strictement plus grand que $n$.</li></ol>`,
  decode: { donnees: [R`(c) Un nombre premier est un entier $\geqslant2$ dont les seuls diviseurs positifs sont $1$ et lui-même.`], but: R`Trois démonstrations courtes.`, cles: {} },
  steps: [
    { q: 1, t: "(a) Forme canonique", h: R`<p>$x^2+x = \left(x+\frac12\right)^2-\frac14$.</p>`, b: R`<p>On complète le carré avec l'identité $(x+a)^2 = x^2+2ax+a^2$ et $a = \frac12$ : $\left(x+\frac12\right)^2 = x^2+x+\frac14$. Donc</p>$$x^2+x+1 = \left(x+\frac12\right)^2-\frac14+1 = \left(x+\frac12\right)^2+\frac34.$$<p>Un carré est $\geqslant0$, donc $x^2+x+1\geqslant\frac34>0$ pour tout réel $x$.</p>` },
    { q: 2, t: "(b) Produit nul", h: R`<p>Si $a\neq0$, multiplie par $\frac1a$.</p>`, b: R`<p>Soient $a,b$ réels avec $ab = 0$. On veut : $a = 0$ ou $b = 0$. Si $a = 0$, c'est fini. Sinon $a\neq0$, donc $a$ a un inverse $\frac1a$, et on multiplie l'égalité $ab = 0$ par $\frac1a$ :</p>$$b = \frac1a\cdot(ab) = \frac1a\cdot0 = 0.$$<p>Dans tous les cas, $a = 0$ ou $b = 0$.</p>`, rappels: ["lg-disjonction"] },
    { q: 3, t: "(c) Un premier plus grand que n", h: R`<p>Regarde $N = n!+1$ et son plus petit diviseur $\geqslant2$.</p>`, b: R`<p>Soit $n\in\mathbb N$ et $N = n!+1$, avec $n! = 1\times2\times\dots\times n$ (et $0! = 1$). On a $N\geqslant2$.</p><p><b>$N$ a un diviseur premier.</b> Soit $p$ le plus petit diviseur de $N$ qui est $\geqslant2$ (il en existe, $N$ lui-même). Si $p$ n'était pas premier, il s'écrirait $p = ab$ avec $2\leqslant a< p$ ; alors $a$ divise $p$, qui divise $N$, donc $a$ divise $N$ : c'est un diviseur $\geqslant2$ plus petit que $p$, absurde. Donc $p$ est premier.</p><p><b>$p>n$.</b> Par l'absurde, si $p\leqslant n$, alors $p$ est l'un des facteurs de $n! = 1\times2\times\dots\times n$, donc $p$ divise $n!$. Il divise aussi $N$, donc il divise la différence $N-n! = 1$. Mais $p\geqslant2$ ne divise pas $1$ : contradiction.</p><div class="sbox"><p style="margin:0">Pour tout $n\in\mathbb N$, il existe un nombre premier $p>n$ : il y a une infinité de nombres premiers.</p></div>`, rappels: ["absurde"] }
  ],
  piege: R`En (c), affirmer que $n!+1$ est premier : c'est faux en général ($5!+1 = 121 = 11^2$). On utilise seulement un de ses diviseurs premiers.`,
  methode: R`Pour un signe : forme canonique. Pour « $A$ ou $B$ » : supposer non $A$ et montrer $B$.`
},
{ id: "lg-somme-produit", ...C0, level: 2, time: "15 min",
  title: "Quand un réel est-il à la fois somme et produit de deux réels ?",
  enonce: R`<p>Déterminer les réels $s$ pour lesquels il existe deux réels $a$ et $b$ tels que</p>$$a+b = s\qquad\text{et}\qquad ab = s.$$`,
  decode: { donnees: [R`Deux réels de somme et de produit connus sont les racines d'un trinôme.`], but: R`Trouver une condition nécessaire et suffisante sur $s$.`, cles: {} },
  steps: [
    { q: 1, t: "Analyse : un trinôme", h: R`<p>Développe $(t-a)(t-b)$.</p>`, b: R`<p><b>Analyse.</b> Supposons qu'il existe $a,b$ réels avec $a+b = s$ et $ab = s$. On développe :</p>$$(t-a)(t-b) = t^2-(a+b)t+ab = t^2-st+s.$$<p>Donc $a$ et $b$ sont des racines réelles du trinôme $t^2-st+s$. Un trinôme a des racines réelles si et seulement si son discriminant est positif :</p>$$\Delta = s^2-4s = s(s-4)\geqslant0.$$<p><b>Signe d'un produit</b> : $s(s-4)\geqslant0$ quand $s$ et $s-4$ ont le même signe (ou l'un est nul), c'est-à-dire $s\leqslant0$ ou $s\geqslant4$.</p>` },
    { q: 2, t: "Synthèse", h: R`<p>Si $\Delta\geqslant0$, prends $a$ et $b$ les deux racines.</p>`, b: R`<p><b>Synthèse.</b> Soit $s\leqslant0$ ou $s\geqslant4$. Alors $\Delta = s^2-4s\geqslant0$ et le trinôme $t^2-st+s$ a deux racines réelles</p>$$a = \frac{s-\sqrt{s^2-4s}}2,\qquad b = \frac{s+\sqrt{s^2-4s}}2.$$<p>On vérifie : $a+b = \frac{2s}2 = s$, et avec $(u-v)(u+v) = u^2-v^2$ :</p>$$ab = \frac{s^2-(s^2-4s)}4 = \frac{4s}4 = s.$$<div class="sbox">$$\exists a,b\in\mathbb R,\ a+b = ab = s\iff s\in\,]-\infty,0]\cup[4,+\infty[.$$</div><p>Exemples : $s = 4$ avec $a = b = 2$ ; $s = 0$ avec $a = b = 0$ ; $s = -1$ avec $a,b = \frac{-1\mp\sqrt5}2$.</p>` }
  ],
  piege: R`S'arrêter à l'analyse : elle donne une condition nécessaire ; la synthèse montre qu'elle est suffisante.`,
  methode: R`Analyse-synthèse : supposer qu'une solution existe pour trouver des conditions, puis vérifier que ces conditions suffisent.`
}
]);
const T = {
  "lg-sqrt2": R`$\sqrt2$ est irrationnel`,
  "lg-sqrt2-somme": R`Rationnel plus $\sqrt2$, et rationnels comme sommes d'irrationnels`,
  "lg-parite-cube": R`$\frac{n(n^2+1)}2$ est un entier naturel`,
  "lg-epsilon": R`Un réel plus petit que tout $\varepsilon$ est nul`,
  "lg-parties": R`Lire une condition sur $x$ comme une partie de $\mathbb R$`,
  "lg-q-pqr": R`Trois propriétés d'une fonction continue`
};
window.LEMME.EXERCISES.forEach(e => { if (T[e.id]) e.tt = T[e.id]; });
})();
